import json

s = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
closer_to_opener = {")": "(", "]": "[", "}": "{", ">": "<"}
opener_to_closer = {v: k for k, v in closer_to_opener.items()}

tokens = s.split()
stack = []
consistent = True
for t in tokens:
    if t in opener_to_closer:
        stack.append(t)
    elif t in closer_to_opener:
        if not stack or stack[-1] != closer_to_opener[t]:
            consistent = False
            break
        stack.pop()
    else:
        consistent = False
        break

if not consistent:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {"tokens": len(tokens), "consistent": False},
    }
else:
    completion = "".join(opener_to_closer[o] for o in reversed(stack))
    result = {
        "final_answer": completion,
        "evidence": {
            "tokens": len(tokens),
            "consistent": True,
            "unclosed_stack_bottom_to_top": stack,
            "completion_length": len(completion),
        },
    }

print(json.dumps(result, separators=(",", ":")))
